import styled from 'styled-components';
import { breakpoints } from '../utils/mediaQueries';

/**
 * ResponsiveGrid - Componente de Grid Mobile-First
 * ===============================================
 * Comportamento padrão: 1 coluna (mobile)
 * Ajusta automaticamente para mais colunas em telas maiores
 * 
 * Props:
 * - $columns: número máximo de colunas (default: 4)
 * - $gap: espaçamento entre itens (default: '1rem')
 * - $minChildWidth: largura mínima de cada filho (default: '280px')
 */

const ResponsiveGrid = styled.div`
  display: grid;
  gap: ${props => props.$gap || 'var(--space-md)'};
  
  /* Mobile: 1 coluna (default) */
  grid-template-columns: 1fr;
  
  /* Phablet (480px+): 2 colunas */
  @media (min-width: 480px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  /* Tablet (768px+): 3 colunas se columns >= 3 */
  @media (min-width: 768px) {
    grid-template-columns: ${props => {
    const cols = Math.min(props.$columns || 4, 4);
    if (cols >= 3) return 'repeat(3, 1fr)';
    if (cols >= 2) return 'repeat(2, 1fr)';
    return '1fr';
  }};
  }
  
  /* Laptop (1024px+): colunas configuradas */
  @media (min-width: 1024px) {
    grid-template-columns: ${props => {
    const cols = props.$columns || 4;
    return `repeat(${cols}, 1fr)`;
  }};
  }
  
  /* Desktop grande (1280px+): ajusta gap */
  @media (min-width: 1280px) {
    gap: ${props => {
    const gap = props.$gap;
    if (typeof gap === 'string' && gap.includes('var(--space')) {
      return gap.replace('md', 'lg').replace('1rem', '1.5rem').replace('16px', '24px');
    }
    return 'var(--space-lg)';
  }};
  }
  
  /* Mobile pequeno (375px): gap menor */
  @media (max-width: 375px) {
    gap: var(--space-sm);
  }
`;

export default ResponsiveGrid;
